import { useEffect, useMemo, useState, type FormEvent, type ReactNode } from "react";
import {
  Activity, ArrowDownRight, ArrowRight, ArrowUpRight, BarChart3, Bell, Boxes,
  Building2, CalendarDays, Check, ChevronDown, ChevronLeft, ChevronRight,
  CircleHelp, Clock3, CreditCard, Download, Eye, FileText, Filter, Gift,
  LayoutDashboard, LogIn, LogOut, Menu, MoreHorizontal, Package, Plus,
  QrCode, Search, Settings, ShieldCheck, ShoppingBag, ShoppingCart, Sparkles,
  Store, Ticket, TrendingUp, Users, Wallet, X, Zap
} from "lucide-react";
import { supabase, isSupabaseConfigured } from "./lib/supabase";
import { loadAcoWorkspace, createFreeBusiness, createProductForStore, completeSale, redeemBusinessActivation, generateActivationCodes, getPlatformOverview, inviteEmployee, markAttendance, createCustomer, createCustomerTab, recordCustomerTabPayment, createReservation, updateReservationStatus, getPublicStoreCatalog, submitPublicQrOrder, getPublicOrderQueue, createStore, reviewQrPayment, updateQrOrderStatus } from "./lib/acopos";

type View = "overview" | "onboarding" | "admin" | "pos" | "products" | "orders" | "branches" | "employees" | "attendance" | "kasbon" | "reservations" | "reports" | "qr" | "members" | "settings" | "activation";
type Product = { id: string | number; name: string; category: string; price: number; stock: number; sku: string };
type Order = { id: string; customer: string; total: number; status: string; time: string; items: number };
